package net.civeira.phylax.features.access.oauthclient.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class FrontchannelLogoutSessionRequiredVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property frontchannel logout session required of oauth client ")
  void test_frontchannel_logout_session_required_v_o_builder() {
    Assertions.assertFalse(
        FrontchannelLogoutSessionRequiredVO.nullValue().isFrontchannelLogoutSessionRequired(),
        "A empty vo should have a null value");
    Assertions.assertFalse(
        FrontchannelLogoutSessionRequiredVO.tryFrom(null).isFrontchannelLogoutSessionRequired(),
        "With a null value, no present result");
    Assertions.assertEquals(true,
        FrontchannelLogoutSessionRequiredVO.from(true).isFrontchannelLogoutSessionRequired());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> FrontchannelLogoutSessionRequiredVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + true + "]",
        FrontchannelLogoutSessionRequiredVO.from(true).toString());
  }
}
